  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 12, 10, 8, 4, '{"niche_fit": "Distinctive single-plant, science-led skincare with a strong ingredient story \u2014 well suited to skincare-education creators.", "ugc_evidence": "The program is explicitly content-led: approved affiliates receive a product bundle specifically to create and share content.", "compensation": "10% commission published on the brand''s own page, paid monthly via PayPal at a $50 AUD threshold per the program terms; no cap statement published.", "contact_access": "Application on the brand''s own page plus a published program email in the terms.", "opportunity_availability": "Open application on the official site, subject to approval.", "credibility": "Award-winning Australian brand with 12+ years of extraction research behind its products."}'::jsonb);
