  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Rajuva Ambassador Program (no cap on commissions; rate 15% vs 30% conflict on page)', 'https://rajuva.com/pages/ambassador-program', 'https://rajuva.com/pages/ambassador-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rajuva.com/pages/ambassador-program', 'official_site', 'affiliate', 'Rajuva''s own Ambassador Program page states ''Earn commissions when someone you referred makes a purchase. No cap on commissions!'' — an explicit no-cap statement on the brand''s own page, so the cap is recorded as uncapped. Ambassadors get a custom referral code/link, their community gets 25% off first orders, and commissions are paid via PayPal or check.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rajuva.com/pages/ambassador-program', 'official_site', 'compensation', 'RATE CONFLICT on the same page: the headline says ''Earn 15% Commission & Rewards!'' while the FAQ states ''you earn 30% of their order total'' and ''You''ll earn 30% commission on every purchase that uses your unique referral code.'' Because the brand''s own page contradicts itself, commission_rate is recorded as null.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 13, 14, 7, 9, 3, '{"niche_fit": "Collagen and vitamin-C-serum ''beauty from within'' products fit wellness and skincare creators, though the range is narrower than a pure beauty brand.", "ugc_evidence": "A named ambassador program built around customers sharing personal results stories on social channels with a personal code.", "compensation": "Verified uncapped \u2014 the brand''s own page says ''No cap on commissions!'' \u2014 but the rate itself is contradicted on the same page (15% headline vs 30% FAQ), so the rate is null and compensation scores mid-range.", "contact_access": "Application route on the program page; no direct partnerships email published.", "opportunity_availability": "Open ambassador sign-up on the official site.", "credibility": "Small doctor-developed brand, products made in the USA; limited public footprint."}'::jsonb);
