  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'EconomyBookings Affiliate Program (60% revenue share)', 'https://www.economybookings.com/en//affiliate/', 'https://www.economybookings.com/en//affiliate/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.economybookings.com/en//affiliate/', 'official_site', 'affiliate', 'EconomyBookings'' own affiliate page states: ''60% of every commission we earn goes straight to you. No caps, no limits.'' and ''Earn 60% of every commission on every completed booking. No minimums, no caps.'' — an explicit no-earnings-cap statement, so commission_cap is uncapped. The 60% is a revenue share of the platform''s own commission (worked example on the page: a €350 booking at a 15% platform commission of €52.50 pays the partner €31.50, plus €9.84 on add-ons).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.economybookings.com/en//affiliate/', 'official_site', 'affiliate', 'The page specifies a 30-day cookie, free signup in about 2 minutes, a dedicated partner manager, and explicitly courts bloggers and influencers (''Monetize your travel content on Instagram, TikTok, YouTube, or your blog''); it reports 600+ active partners — a partner count in the hundreds, so creator_saturation stays unknown under the absolute-terms rule.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.economybookings.com/en//affiliate/', 'official_site', 'general', 'The page lists 18+ years in the industry, 600+ suppliers, 150+ countries and 30,000+ locations, and a ''Top 500 Largest Companies in Latvia 2023–2024'' award among its recognitions, supporting the Latvia base.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 20, 8, 9, 5, '{"compensation": "60% revenue share of the platform''s commission with an explicit ''No caps, no limits'' statement on the brand''s own page \u2014 the strongest verified compensation terms in this group.", "contact_access": "No public affiliate email is published; partners get a dedicated manager only after signup, so contact access is mid-range.", "credibility": "18+ years operating, 600+ suppliers, 150+ countries, industry awards and a published partner-payout track record.", "niche_fit": "Car rentals are a core travel-creator monetisation category, and the brand''s own page explicitly targets travel bloggers and social creators.", "opportunity_availability": "Open self-serve signup on the brand''s own page, live in about 5 minutes with no technical skills required.", "ugc_evidence": "The official affiliate page has a dedicated ''Bloggers & Influencers'' track naming Instagram, TikTok, YouTube and blogs as monetisable channels."}'::jsonb);
