  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.guruwalk.com/portal/en/kb/articles/what-requirements-should-i-meet-to-enter-the-programme', 'official_site', 'affiliate', 'GuruWalk''s own support article states: ''You don''t need to have tourist accommodation, a blog or a website... Anyone can become an affiliate and achieve results by promoting tours via WhatsApp, social media or any other channel. The program is open to everyone.'' Joining is completely free; signup is at guruwalk.com/afiliados.', 'verified', now());
