  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://kit.com/resources/blog/best-affiliate-programs-for-bloggers?lmref=ousmwa', 'listing', 'affiliate', 'Kit''s affiliate roundup lists ModCloth at 7% on ShareASale, while other directories list 5% (Empire Flippers'' fashion affiliate guide; bloggerteck''s clothing program list) and one lists a 5%–20% range (tasklanding). Because published sources conflict on the current rate, commission_rate is null and the conflict is documented here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliatetips.blog/fashion-affiliate-programs-share-a-sale/', 'listing', 'affiliate', 'AffiliateTips'' ShareASale fashion list gives ModCloth''s ShareASale signup (merchantID 45519) plus a LinkShare/Rakuten signup link and quotes 5% commission (2% on deals and discounts) with a 30-day cookie — confirming the program''s network presence and adding to the rate conflict.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 6, 5, 8, 4, '{"compensation": "Published rates conflict (5% vs 7% vs a 5%\u201320% range), so no rate is recorded and compensation scores low until the brand confirms current terms.", "contact_access": "No public affiliate contact found; access is through the ShareASale merchant page only.", "credibility": "A well-known US online fashion retailer operating for many years with a large catalogue.", "niche_fit": "Vintage-inspired, size-inclusive women''s fashion with a distinctive aesthetic that suits style creators.", "opportunity_availability": "Open application via ShareASale with reported fast approval.", "ugc_evidence": "A long-running network affiliate program with banners, links and a product datafeed reported by directories, but no public creator program page of its own."}'::jsonb);
