  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.firsty.app/partners/affiliates', 'official_site', 'affiliate', 'Firsty''s own affiliate page invites bloggers, influencers and creators, and travel/lifestyle creators specifically: affiliates get a personal link and exclusive discount code, ''promote with full creative freedom'', and track signups and commissions; applications are reviewed by the Firsty team. The page publishes no commission percentage.', 'verified', now());
