  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 15, 14, 8, 8, 4, '{"compensation": "15% commission per OffersPilot''s directory (30-day cookie) \u2014 a competitive eSIM rate, though Firsty''s own page does not publish the figure.", "contact_access": "A general support email appears on the partner pages; there is no dedicated affiliate inbox published.", "credibility": "Amsterdam startup founded 2023 with institutional seed funding and award recognition in the MVNO/eSIM space.", "niche_fit": "Travel eSIM is a natural, repeatable recommendation for travel creators, and Firsty''s free tier lowers the barrier for audiences.", "opportunity_availability": "Public application on the brand''s own page, subject to team approval.", "ugc_evidence": "The brand''s own affiliate page is written directly for influencers and travel/lifestyle creators, with creative freedom promised."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Auto Europe', 'https://www.autoeurope.com', 'Car rental broker founded in 1954, comparing rental prices across 180+ countries and 24,000+ locations; its affiliate offer runs through Travelpayouts, with rates that vary by the Auto Europe domain used and the affiliate''s audience region.', 'United States', 'published') returning id into bid;
