  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Auto Europe Affiliate Program (Travelpayouts)', 'https://www.travelpayouts.com/brands-directory/car_bike_rental/', 'https://www.travelpayouts.com/brands-directory/car_bike_rental/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/brands-directory/car_bike_rental/', 'affiliate_network', 'affiliate', 'Travelpayouts'' own brands directory lists AutoEurope (EU, UK) at 4.4%–8% — ''The partner commission depends on the domain where the booking is made: 4.4% for autoeurope.co.uk, 8% for all other domains'' — with a 30-day cookie lifetime.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/auto-europe/', 'listing', 'affiliate', 'Lasso lists the Auto Europe affiliate offer at 2.4%–5.6% per sale with a 7-day cookie (the US/Canada-audience variant described in Travelpayouts materials), while Auto Europe''s own UK affiliate page says commissions ''normally start at 5%''. Because the applicable rate depends on domain and audience and the sources describe different schedules, commission_rate is null and the schedules are documented here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/tag/autoeurope/', 'affiliate_network', 'general', 'Travelpayouts'' AutoEurope posts describe joining the program to ''earn up to 8% commission on car rentals in over 24,000 locations across 180 countries''.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 9, 9, 5, 8, 5, '{"compensation": "Documented schedules run 4.4%\u20138% (EU/UK offer) and 2.4%\u20135.6% (US/CA offer) of the booking amount \u2014 usable, but no single rate applies, so none is recorded.", "contact_access": "No public affiliate email found; contact runs through the Travelpayouts network dashboard.", "credibility": "Operating since 1954 with inventory in 180+ countries and 24,000+ locations \u2014 one of the longest-established car rental brokers.", "niche_fit": "Car rental is a standard travel-content monetisation category, though the program is pitched mainly at website owners rather than social creators.", "opportunity_availability": "Open to join through Travelpayouts with easy approval reported by directories.", "ugc_evidence": "Program materials target content-led travel affiliates and bloggers; there is no dedicated creator or ambassador layer."}'::jsonb);
