  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://drinkatlys.com/athletes', 'official_site', 'affiliate', 'ATLYS Athletes is the brand''s own commission program, open to U.S. residents at every level from grade school to the pros: apply, get hand-approved, receive a personal code/link, and earn $5 for every ATLYS One sold through it while followers get 10% off. The page states plainly it is commission-based — no free product or merch for joining.', 'verified', now());
