  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Au Bon Broth Affiliate Program — 20% commission, brand-direct (own published affiliate agreement; $100 payout minimum)', 'https://www.aubonbroth.com/aba-affiliate-agreement', 'https://www.aubonbroth.com/aba-affiliate-agreement', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.aubonbroth.com/aba-affiliate-agreement', 'official_site', 'affiliate', 'Au Bon Broth''s own published Affiliate Agreement (last updated Mar 6, 2023) sets the General Affiliate commission at 20% of the total sale amount excluding taxes and fees, paid in USD on the 1st and 15th of each month after a 45-day refund window. Caution terms: a $100 minimum must be reached, and commissions under $100 within a 120-day period are forfeited; affiliates must use @AuBonBoneBroth / #AuBonBoneBroth and #ad disclosures on social posts.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 15, 10, 7, 3, '{"compensation": "20% of the sale amount on the brand''s own published agreement \u2014 a high, verified rate; held back by the $100 minimum and a 120-day forfeiture clause.", "contact_access": "Published support email and the full program agreement on the brand''s own site.", "credibility": "Terms date from March 2023 and the forfeiture clause is unusually harsh, so credibility is scored conservatively.", "niche_fit": "Bone broth fits wellness, keto and gut-health content, though it is a narrower single-product niche.", "opportunity_availability": "Application-based with approval at the brand''s discretion (''not everyone who applies will qualify'').", "ugc_evidence": "The agreement includes detailed social-media promotion rules for affiliates (hashtags, Paid Partnership tools), showing creator promotion is an intended channel, but no public creator roster was found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Optery', 'https://www.optery.com', 'Personal data removal service that finds and removes customers'' personal information from data broker sites, ranked #1 most effective in a Consumer Reports study and a multi-year PCMag Editors'' Choice winner; its affiliate program pays 30% commission for the first 12 months per referred customer, in cash, through PartnerStack.', 'United States', 'published') returning id into bid;
