  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Optery Affiliate Program — 30% for 12 months via PartnerStack, verified uncapped', 'https://www.optery.com/affiliate-program/', 'https://www.optery.com/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.optery.com/affiliate-program/', 'official_site', 'affiliate_program', 'Optery''s own affiliate program page (fetched first-hand) invites businesses, professional influencers and marketers with websites, newsletters or social channels to apply via PartnerStack, states payouts are in cash (not credits or gift cards), and says no website is required — social media promotion is accepted.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.optery.com/affiliate-program/', 'official_site', 'compensation', 'The page''s FAQ states the commission plainly: ''30% commission for the first 12 months of sales for each new customer you refer'' across Monthly, Yearly, Personal, Family and Business plans (example given: $75 per list-price Ultimate yearly subscription), with commissions processed 35 days after each referred transaction and a 90-day tracking window per click.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.optery.com/affiliate-program/', 'official_site', 'commission_cap', 'VERIFIED UNCAPPED: the page''s FAQ asks ''Is there a maximum amount of commission I can earn?'' and answers ''No. Currently there is no maximum on the amount of commission you can earn.'' — an explicit no-cap statement on the brand''s own page, so commission_cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.optery.com/affiliate-program/', 'official_site', 'general', 'The page states Optery is a Delaware C corporation headquartered in the San Francisco Bay Area, SOC 2 Type II compliant, ranked #1 most effective in a recent Consumer Reports study and PCMag Editors'' Choice 2022-2025; it publishes no creator-count figure, so creator_saturation is honestly recorded as unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 18, 10, 9, 5, '{"niche_fit": "Pure consumer privacy/security software \u2014 a core technology niche for creator reviews and ''remove your data'' content.", "ugc_evidence": "The brand''s own page explicitly recruits professional influencers and marketers with social channels and says no website is required.", "compensation": "30% of every sale for a full 12 months per referred customer, paid in cash \u2014 a top-tier rate for this category, and verified uncapped.", "contact_access": "Application runs through PartnerStack from the brand''s own page with personalized support promised; no public program email is published.", "opportunity_availability": "Public application open to businesses, influencers and marketers; approval required but being an Optery customer is explicitly not required.", "credibility": "Delaware C corporation, SOC 2 Type II, Consumer Reports #1 effectiveness ranking and four straight PCMag Editors'' Choice awards."}'::jsonb);
