  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 15, 8, 8, 5, '{"niche_fit": "A flagship consumer VPN \u2014 one of the most-reviewed products in the technology creator niche.", "ugc_evidence": "A long-running affiliate program with banners, videos and targeted landing pages supplied to promoters, though its FAQ is written for existing affiliates rather than creator recruitment.", "compensation": "Flat CPA of $13-$36 per subscription depending on plan length, published on the brand''s own FAQ \u2014 solid per-sale pay, but no recurring component.", "contact_access": "A published accounts email on the brand''s own FAQ plus application through Impact; no dedicated creator inbox is published.", "opportunity_availability": "Applications run through the Impact network campaign page; approval is required and coupon sites are typically not accepted.", "credibility": "One of the largest and longest-established consumer VPN brands in the world."}'::jsonb);
