  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 17, 8, 8, 5, '{"niche_fit": "All-in-one digital safety (identity, credit, VPN, antivirus, passwords) \u2014 a heavily promoted category in tech and family-safety content.", "ugc_evidence": "A public affiliate page recruiting partners with a dedicated account manager and conversion support, though pitched at affiliates generally rather than creators specifically.", "compensation": "Flat $65 per qualified enrollment is a high per-conversion bounty for a consumer subscription, paid monthly net-30.", "contact_access": "Application through Impact from the brand''s own page with a dedicated account manager promised; no public program email is published.", "opportunity_availability": "Public join route via Impact; approval terms are not detailed on the page.", "credibility": "The company behind Identity Guard, with #1 ratings from US News and Security.org and an A+ BBB rating shown on its own page."}'::jsonb);
