  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliateotter.com/affiliate-programs/1password', 'listing', 'affiliate', 'AffiliateOtter''s validated program profile (validated 21 Jan 2026) records that 1Password''s official program page promotes a $2 completed-signup bounty plus 25% of the first year or first month''s payment with a $2 minimum, and directs applicants to create a Commission Junction (CJ) account and apply to the 1Password program there; a separate PartnerStack listing also exists.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://scoutner.com/programs/1password', 'listing', 'compensation', 'Scoutner''s profile, checked against 1Password''s official affiliate page on 30 Sep 2026, confirms the same structure verbatim — $2 per completed signup plus 25% of the first year or month''s payment ($2 minimum), run on Commission Junction — and notes the official page publishes no cookie duration.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://1password.com/affiliate', 'official_site', 'affiliate_program', 'When fetched first-hand for this batch, 1password.com/affiliate presented the 1Password Partner Program (channel partners, MSPs and alliances) rather than the consumer affiliate offer, so the affiliate terms rest on the two directory profiles above that read the official affiliate page directly; flagged needs_review so the CJ listing can be re-confirmed at application time. No fetched page states an earnings cap or creator count, so both fields are honestly unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 14, 6, 7, 5, '{"niche_fit": "A mainstream password manager used by individuals and families \u2014 a staple recommendation in tech and security content.", "ugc_evidence": "An established affiliate program on CJ with links and banners for publishers, though the brand does little creator-specific recruitment on its public pages.", "compensation": "A hybrid $2 per completed signup plus 25% of the first payment balances volume and value; first-year-only, so no renewal tail.", "contact_access": "Application runs inside CJ after creating a publisher account; no public program email or creator application page could be confirmed.", "opportunity_availability": "Open to CJ publishers subject to manual approval; the public affiliate page currently surfaces the partner program, which adds friction.", "credibility": "One of the most recognized and trusted password-management brands in the world."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Proton', 'https://proton.me', 'Swiss privacy company behind Proton Mail, Proton VPN, Proton Drive, Proton Pass and Proton Calendar; its in-house Partners Program pays tiered commissions across the suite — 100% of the first month on monthly plans, 40% on one- and two-year plans, and 30% on renewals — paid by bank transfer once a balance passes $100.', 'Switzerland', 'published') returning id into bid;
