  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ancaster.io/offers/proton', 'listing', 'affiliate', 'Ancaster''s program profile, verified 24 Aug 2026 from Proton''s own published material, records the tiered structure — up to 100% commission on new monthly sign-ups, 40% on 1-2 year plans, roughly 30% on renewals — applied for directly through Proton''s own application form with no third-party network, paid by bank transfer on the 30th of the following month once the balance exceeds $100. Because the rate is tiered rather than a single figure, commission_rate is recorded as null and the tiers documented here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliateotter.com/affiliate-programs/protonvpn', 'listing', 'compensation', 'AffiliateOtter''s validated profile (validated 22 Jun 2026) confirms the official Proton Partners page advertises up to 100% commission for new referrals plus recurring revenue on renewals, with commissions paid by direct bank transfer on the 30th of the next calendar month when the payable balance exceeds $100.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ancaster.io/offers/proton', 'listing', 'commission_cap', 'Ancaster notes the published commission table pays a rate on renewals with no separate cap on the number of months or years published — that is an absence of a stated duration limit, not an explicit no-earnings-cap statement, so under the strict filter commission_cap is honestly recorded as unknown; no creator-count figure is published either.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 17, 6, 7, 5, '{"niche_fit": "The leading privacy suite (mail, VPN, drive, passwords) \u2014 a core brand for privacy and tech creators.", "ugc_evidence": "The Partners Program explicitly includes influencers among its partner types per profiles of the official page, alongside affiliates and resellers.", "compensation": "Front-loaded tiers (100% of the first month, 40% on annual plans) plus 30% on renewals make this one of the richest published structures in consumer software.", "contact_access": "Direct application through Proton''s own partner page; no public program email is published.", "opportunity_availability": "Open direct application with manual review; the $100 payout threshold is higher than most programs here.", "credibility": "Switzerland-based, one of the most trusted names in consumer privacy with a huge global user base."}'::jsonb);
