  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 10, 5, 8, 4, '{"niche_fit": "Home water filtration (RO systems, faucet and countertop filters) \u2014 a practical home niche with strong review and installation content potential.", "ugc_evidence": "The brand actively recruits creator collaborations for product launches through creator platforms and runs affiliate, distributor and dropshipper programs from its homepage.", "compensation": "8% default per sale on FlexOffers, rising to 16% on the LP365 \u2014 a mid-range hardware rate; filters pay 4%.", "contact_access": "No public program email or contact is published on the fetched pages; contact runs through the network.", "opportunity_availability": "Live and accepting publishers on FlexOffers (and mirrored on other networks), with deep links supported.", "credibility": "An established filtration brand with US and European sales and network-verified program data, though less prominent than the software brands in this group."}'::jsonb);
