  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lockin.com/pages/affiliate-program', 'official_site', 'affiliate_program', 'Lockin''s own affiliate program page (fetched first-hand) states the program ''invites review websites, online communities, bloggers, and other content creators to promote our smart lock products'' and that affiliates earn commissions when users complete purchases on lockin.com through their referral links; it lays out the apply-then-promote flow and says publishers can create custom links to any URL on lockin.com through affiliate network toolkits and the brand''s product data feed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lockin.com/pages/affiliate-program', 'official_site', 'compensation', 'The brand''s page publishes no commission rate, percentage or bounty figure anywhere — commissions are described only as accumulating as orders are placed — so commission_rate is honestly recorded as null rather than guessed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lockin.com/pages/affiliate-program', 'official_site', 'commission_cap', 'No earnings-cap statement and no creator-count figure appear on the fetched page, so commission_cap and creator_saturation are honestly recorded as unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 4, 6, 8, 4, '{"niche_fit": "Consumer smart locks and home security \u2014 a demonstrable smart-home product for review and installation content.", "ugc_evidence": "The brand''s own page explicitly recruits bloggers, review sites and content creators and supports custom deep links and a product data feed.", "compensation": "No commission rate or bounty is published anywhere on the program page, so this stays at the no-data level until terms are confirmed inside the application.", "contact_access": "A public application route on the brand''s own page; support contact is offered for content-use reviews, but no program email is published.", "opportunity_availability": "Public application open to bloggers, communities and creators in home security and smart home niches.", "credibility": "An established smart-lock brand with its own storefront and a detailed, rule-published affiliate program page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Shep', 'https://www.shep.pet', 'Pet protection platform built with The Sanctuary Project rescue, combining pet care plans (Plus and Complete) with legal trusts, guardian designation and care-continuity tools; its Shep Advocate program pays creators and pet businesses $12 per Plus signup or $25 per Complete signup, plus 20% of every payment the referred customer makes in their first 12 months.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.shep.pet/advocate', 'https://www.shep.pet/advocate', 'verified', now());
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'hello@shep.pet', null, 'https://www.shep.pet/advocate', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Direct (own Advocate program)', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.shep.pet/advocate.', 'https://www.shep.pet/advocate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Shep Advocate Program — $12/$25 signup bounties + 20% of payments for 12 months', 'https://www.shep.pet/advocate', 'https://www.shep.pet/advocate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shep.pet/advocate', 'official_site', 'affiliate_program', 'Shep''s own Advocate page (fetched first-hand) recruits ''pet lifestyle creators, dog trainers, groomers, pet sitters & walkers, boarding & daycare, rescue advocates, breed communities and pet photographers'', states ''Fit and how much your people listen to you matter more to us than follower count'', and explains that every application is read personally and answered; larger organizations are directed to hello@shep.pet, published on the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shep.pet/advocate', 'official_site', 'compensation', 'The page publishes the pay structure plainly: ''$12 when someone starts Plus, or $25 for Complete. Then get 20% of every payment they make in their first 12 months'' — only paid plans count, and the 20% follows what the customer actually pays. The 20% recurring share is recorded as the commission rate, with the flat signup bounties documented here.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shep.pet/advocate', 'official_site', 'commission_cap', 'No earnings-cap statement appears on the fetched page, and while the program is clearly small and personally run, no absolute creator-count figure is published, so commission_cap and creator_saturation are honestly recorded as unknown rather than inferred.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 18, 16, 13, 8, 4, '{"niche_fit": "A pet protection and care platform built with a rescue organization \u2014 squarely in the pet niche with a strong story angle for creators.", "ugc_evidence": "The program is built for creators first: it supplies photos and ready-to-share copy, plans co-marketing posts and events with advocates, and explicitly says follower count does not matter.", "compensation": "Flat $12/$25 signup bounties plus 20% of every payment for a full year is a rich hybrid structure for a young program.", "contact_access": "A public application page plus a published partnerships email (hello@shep.pet) and a named human who reads and answers every application.", "opportunity_availability": "Applications are open to solo creators and pet businesses of any size, subject to personal review rather than follower thresholds.", "credibility": "A young company, but transparent about its rescue partnership (The Sanctuary Project, 2,000+ placements over 16 years) and its exact pay terms."}'::jsonb);
